test('privacy reminder assessment follows original civil dates and current reviewed targets without queueing or private content',async()=>{
 const f=await operationsFixture();try{const today=(await f.pg.query<{today:string}>("SELECT (statement_timestamp() AT TIME ZONE 'America/Toronto')::date::text today")).rows[0].today,created=await f.request('privacy-requests',{...input,subjectId:f.actors.staff.person,receivedAt:today+'T00:00:00Z',timeZone:'America/Toronto'});assert.equal(created.response.status,201,JSON.stringify(created.body));const id=created.body.data.id,path='privacy-requests/'+id+'/reminder-source',read=(basis='target',days='0',as='master')=>f.request(path+'?'+new URLSearchParams({basis,daysFromTarget:days}),undefined,as),pending=(await f.pg.query('SELECT 1 FROM public.notification_deliveries')).rows.length;
 const first=await read();assert.equal(first.response.status,200,JSON.stringify({body:first.body,errors:f.metrics.queryFailures}));assert.equal(first.body.data.eligible,false);assert.equal(first.body.data.assessmentState,'not_due');assert.equal(first.body.data.timeZone,'America/Toronto');assert.equal(first.body.notificationQueued,false);assert.equal(first.body.data.legalDeadlineVerified,false);assert.doesNotMatch(JSON.stringify(first.body),/PRIVATE|scope|subjectId|requestedBy|receivedAt|session_id|auth_user|phone|email/);
 const definition={state:'under_review',message:'Your request is under review.',privateNote:'PRIVATE_REMINDER_NOTE',reviewReference:'PRIVATE_REVIEW',targetResponseOn:today,delivery:null},reviewed=await f.request('privacy-requests/'+id+'/review',{expectedVersion:1,definition,reason:'Reviewed operational follow-up target'});assert.equal(reviewed.response.status,200,JSON.stringify(reviewed.body));const due=await read();assert.equal(due.body.data.eligible,true);assert.equal(due.body.data.reminderOn,today);assert.equal(due.body.data.responseVersion,2);const baseline=await read('baseline');assert.equal(baseline.body.data.eligible,false);assert.equal(baseline.body.data.targetResponseOn,today);assert.equal(baseline.body.data.selectedReviewOn,created.body.data.baselineReviewOn);assert.equal((await read('target','1')).body.data.assessmentState,'not_due');assert.equal((await read('target','-1')).body.data.assessmentState,'window_expired');
 const self=await f.request('me/privacy-requests',input,'staff');assert.equal(self.response.status,201);assert.equal((await f.request('privacy-requests/'+self.body.data.id+'/reminder-source?basis=target&daysFromTarget=0',undefined,'staff')).response.status,403);
 assert.equal((await f.request('privacy-requests/'+id+'/review',{expectedVersion:2,definition:{...definition,...response(today),delivery:{method:'offline',reference:'Synthetic actual response delivery',deliveredAt:new Date().toISOString()}},reason:'Actual reviewed response'})).response.status,200);const final=await read();assert.equal(final.body.data.eligible,false);assert.equal(final.body.data.assessmentState,'final');assert.equal((await f.pg.query('SELECT 1 FROM public.notification_deliveries')).rows.length,pending);assert.equal((await f.pg.query('SELECT 1 FROM public.finance_journals')).rows.length,0);
 }finally{await f.pg.close();}
});
