const response=(target:string)=>({state:'responded',message:'Reviewed response is now available in this portal.',privateNote:'PRIVATE_INTERNAL_REVIEW_NOTE',reviewReference:'PRIVATE_REVIEW_REFERENCE',targetResponseOn:target,delivery:{method:'portal',reference:'PRIVATE_RESPONSE_REFERENCE'}});
const privacyReportRoot='reports/administration/privacy-requests';
async function privacyReportDates(f:Pick<Awaited<ReturnType<typeof operationsFixture>>,'pg'>){return(await f.pg.query<{from:string;through:string;oldAt:string}>("SELECT ((statement_timestamp() AT TIME ZONE 'UTC')::date-90)::text \"from\",(statement_timestamp() AT TIME ZONE 'UTC')::date::text through,to_char((statement_timestamp()-interval '60 days') AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.MS\"Z\"') \"oldAt\"")).rows[0];}
test('privacy summary reconciles complete receipt cohorts and current state charts without exposing private case data',async()=>{
 const f=await operationsFixture();try{const dates=await privacyReportDates(f),q={from:dates.from,through:dates.through,timeZone:'UTC'},old=await f.request('privacy-requests',{...input,subjectId:f.actors.staff.person,receivedAt:dates.oldAt,timeZone:'America/Toronto'});assert.equal(old.response.status,201,JSON.stringify(old.body));const today=(await f.pg.query<{today:string}>("SELECT (statement_timestamp() AT TIME ZONE 'UTC')::date::text today")).rows[0].today;assert.equal((await f.request('privacy-requests/'+old.body.data.id+'/review',{expectedVersion:1,definition:{state:'under_review',message:'Review underway.',privateNote:'PRIVATE_SUMMARY_REVIEW',reviewReference:'PRIVATE_SUMMARY_REFERENCE',targetResponseOn:today,delivery:null},reason:'Reviewed operational extension'})).response.status,200);const closed=await f.request('me/privacy-requests',{...input,category:'complaint'},'peer');assert.equal(closed.response.status,201);assert.equal((await f.request('me/privacy-requests/'+closed.body.data.id+'/withdraw',{expectedVersion:1,reason:'Withdraw own request'},'peer')).response.status,200);assert.equal((await f.request('me/privacy-requests',{...input,category:'correction'},'staff')).response.status,201);
 const r=await f.request(privacyReportRoot+'?'+new URLSearchParams(q));assert.equal(r.response.status,200,JSON.stringify({body:r.body,errors:f.metrics.queryFailures}));const d=r.body.data;assert.deepEqual(d.summary,{total:3,open:2,overdueBaseline:1,overdueTarget:0,needsInformation:0,oldestOpenReceivedOn:dates.oldAt.slice(0,10)});for(const values of Object.values(d.charts) as {count:number}[][])assert.equal(values.reduce((n,r)=>n+r.count,0),3);assert.equal(d.charts.byState.find((r:{state:string})=>r.state==='withdrawn').count,1);assert.equal(d.legalDeadlineVerified,false);assert.equal(d.permissionsAppliedBeforeAggregation,true);assert.doesNotMatch(JSON.stringify(d),/PRIVATE|details|privateNote|reviewReference|phone|email|source_basis/);for(const id of [old.body.data.id,closed.body.data.id,f.actors.staff.person,f.actors.peer.person])assert.ok(!JSON.stringify(d).includes(id));const filtered=await f.request(privacyReportRoot+'?'+new URLSearchParams({...q,category:'complaint'}));assert.equal(filtered.body.data.summary.total,1);assert.equal(filtered.body.data.summary.open,0);assert.equal((await f.pg.query('SELECT 1 FROM public.finance_journals')).rows.length,0);
 }finally{await f.pg.close();}
});
