test('privacy request notices reveal only a current authorized case link and remain scoped after relationship or role loss',async()=>{
 const f=await agreementFixture();try{const r=await f.request('me/privacy-requests',{...input,subjectId:f.student},'staff');assert.equal(r.response.status,201);const id=r.body.data.id,notices=(await f.request('notifications',undefined,'staff')).body.data.filter((n:{source:{kind:string}})=>n.source.kind==='privacy_request');assert.equal(notices.length,1);assert.equal(notices[0].source.id,id);assert.equal(notices[0].source.recordPath,'/api/v1/privacy-requests/'+id);assert.equal(notices[0].source.caseResolvedByReading,false);assert.equal((await f.request('notifications')).body.data.filter((n:{source:{id:string}})=>n.source.id===id).length,1);assert.equal((await f.request('notifications',undefined,'manager')).body.data.filter((n:{source:{id:string}})=>n.source.id===id).length,0);assert.doesNotMatch(JSON.stringify(notices),/PRIVATE_REQUEST_TEXT|PRIVATE Student|details|privateNote|reviewReference|relationshipId|phone|email/);for(const cap of ['privacy-requests.view','privacy-requests.edit'])await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,$3,'allow')",[f.a,f.managerRole,cap]);assert.equal((await f.request('notifications',undefined,'manager')).body.data.filter((n:{source:{id:string}})=>n.source.id===id).length,1);await f.pg.query("DELETE FROM public.role_permissions WHERE role_id=$1 AND capability='privacy-requests.view'",[f.managerRole]);assert.equal((await f.request('notifications',undefined,'manager')).body.data.filter((n:{source:{id:string}})=>n.source.id===id).length,0);const french=(await f.request('notifications?locale=fr',undefined,'staff')).body.data.find((n:{source:{id:string}})=>n.source.id===id);assert.equal(french.title,'Demande de confidentialité mise à jour');const chinese=(await f.request('notifications?locale=zh-CN',undefined,'staff')).body.data.find((n:{source:{id:string}})=>n.source.id===id);assert.equal(chinese.title,'隐私请求已更新');await f.pg.exec('BEGIN');try{await f.pg.query("SELECT set_config('app.academy_id',$1,true)",[f.a]);await f.pg.exec('SET LOCAL ROLE kavosh_message_worker');await assertRuntimeRole({query:f.pg.query.bind(f.pg),release(){}},'message_worker');assert.equal((await f.pg.query<{allowed:boolean}>('SELECT public.privacy_request_notice_allows($1,$2,$3::jsonb) allowed',[notices[0].eventId,f.signer,'{}'])).rows[0].allowed,true);assert.equal((await f.pg.query<{allowed:boolean}>('SELECT public.privacy_request_notice_allows($1,$2,$3::jsonb) allowed',[notices[0].eventId,f.actors.manager.person,'{}'])).rows[0].allowed,false);assert.equal((await f.pg.query("SELECT has_table_privilege(current_user,'public.privacy_requests','SELECT') permitted")).rows[0].permitted,false);}finally{await f.pg.exec('ROLLBACK');}assert.equal((await f.request('family-relationships/'+f.relationship.id+'/change',{expectedVersion:1,relationship:'authorized_contact',reason:'Synthetic authority ended'})).response.status,200);assert.equal((await f.request('notifications',undefined,'staff')).body.data.filter((n:{source:{id:string}})=>n.source.id===id).length,0);
 }finally{await f.pg.close();}
});
test('privacy receipt and retry cannot commit if its mandatory notice or native source envelope is dropped',async()=>{
 const f=await operationsFixture();try{for(const [table,condition]of [['portal_notifications',"NEW.title='Privacy request updated'"],['automation_event_sources',"NEW.event_type='privacy.request.created'"]]){await f.pg.exec(`CREATE FUNCTION public.synthetic_skip_privacy_notice() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF ${condition} THEN RETURN NULL;END IF;RETURN NEW;END $$;CREATE TRIGGER synthetic_skip_privacy_notice BEFORE INSERT ON public.${table} FOR EACH ROW EXECUTE FUNCTION public.synthetic_skip_privacy_notice()`);const key=randomUUID(),r=await f.request('me/privacy-requests',input,'staff',{key});assert.equal(r.response.status,503,JSON.stringify(r.body));assert.equal((await f.pg.query('SELECT * FROM public.privacy_requests')).rows.length,0);assert.equal((await f.pg.query('SELECT * FROM public.privacy_request_revisions')).rows.length,0);assert.equal((await f.pg.query('SELECT * FROM public.request_keys WHERE key=$1',[key])).rows.length,0);await f.pg.exec(`DROP TRIGGER synthetic_skip_privacy_notice ON public.${table};DROP FUNCTION public.synthetic_skip_privacy_notice()`);}assert.equal((await f.request('me/privacy-requests',input,'staff')).response.status,201);
 }finally{await f.pg.close();}
});
test('actual378to380 preserves existing people policy helpers and held-record coverage with tenant-only privacy sources',async()=>{
 const f=await operationsFixture({throughSchema:378});try{const tables=['people','role_permissions','role_assignments','audit_events','approval_requests'],snapshot=async()=>{const result=[];for(const table of tables)result.push((await f.pg.query('SELECT * FROM public.'+table+' ORDER BY 1,2')).rows);return result;},before=await snapshot(),sql="SELECT oid,proowner,proacl,prosecdef,proconfig FROM pg_proc WHERE oid IN('public.profile_consent_actor_basis(uuid,uuid)'::regprocedure,'public.mandatory_alert_guard()'::regprocedure) ORDER BY oid",helpers=(await f.pg.query(sql)).rows;await upgradeToCurrent(f.pg);assert.deepEqual(await snapshot(),before);assert.deepEqual((await f.pg.query(sql)).rows,helpers);const coverage=(await f.pg.query("SELECT * FROM platform_private.academy_preservation_coverage WHERE relation_name IN('privacy_requests','privacy_request_revisions')")).rows;assert.equal(coverage.length,2);assert.ok(coverage.every(r=>r.delete_guard_present&&r.truncate_guard_present));const made=await f.request('me/privacy-requests',input,'staff');assert.equal(made.response.status,201);await f.pg.exec('BEGIN');try{await f.pg.query("SELECT set_config('app.academy_id',$1,true)",[f.b]);await f.pg.exec('SET LOCAL ROLE kavosh_runtime');assert.equal((await f.pg.query('SELECT * FROM public.privacy_requests')).rows.length,0);assert.equal((await f.pg.query('SELECT * FROM public.privacy_request_revisions')).rows.length,0);assert.equal((await f.pg.query("SELECT has_schema_privilege('kavosh_runtime','public','CREATE') permitted")).rows[0].permitted,false);}finally{await f.pg.exec('ROLLBACK');}for(const d of [{...response(made.body.data.baselineReviewOn),state:null},{...response(made.body.data.baselineReviewOn),delivery:{method:'portal',reference:'Synthetic',deliveredAt:'2026-01-01T00:00:00.000Z'}},{...response(made.body.data.baselineReviewOn),unknown:true}]){assert.equal(privacyResponseDefinition.safeParse(d).success,false);assert.equal((await f.pg.query<{ok:boolean}>('SELECT public.privacy_response_valid($1::jsonb) ok',[JSON.stringify(d)])).rows[0].ok,false);}
 }finally{await f.pg.close();}
});
test('privacy native guards reject an unapproved response even with a valid human and captured source',async()=>{
 const f=await operationsFixture();try{const made=await f.request('me/privacy-requests',input,'staff');assert.equal(made.response.status,201);const id=made.body.data.id;await f.pg.exec('BEGIN');try{await f.pg.query("SELECT set_config('app.academy_id',$1,true)",[f.a]);await f.pg.exec('SET LOCAL ROLE kavosh_runtime');const source=(await f.pg.query<{b:unknown}>('SELECT public.privacy_request_basis($1,1) b',[id])).rows[0].b;await f.pg.query('UPDATE public.privacy_requests SET version=2 WHERE id=$1',[id]);await assert.rejects(f.pg.query('INSERT INTO public.privacy_request_revisions(academy_id,request_id,version,state,definition,source_basis,changed_by,session_id,api_request_id,approval_id,reason) VALUES($1,$2,2,\'responded\',$3::jsonb,$4::jsonb,$5,$6,$7,$8,$9)',[f.a,id,JSON.stringify(response(made.body.data.baselineReviewOn)),JSON.stringify(source),f.actors.master.person,f.actors.master.session,randomUUID(),randomUUID(),'Synthetic forged response']),/PRIVACY_REQUEST_EXACT_REVIEW_REQUIRED/);}finally{await f.pg.exec('ROLLBACK');}assert.equal((await f.request('privacy-requests/'+id,undefined,'staff')).body.data.version,1);assert.equal((await f.pg.query('SELECT * FROM public.privacy_request_revisions')).rows.length,1);
 }finally{await f.pg.close();}
});
test('privacy portal completion stales when guardian authority is lost but a reviewed offline response remains possible',async()=>{
 const f=await agreementFixture();try{for(const cap of ['privacy-requests.view','privacy-requests.edit'])await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,$3,'allow')",[f.a,f.managerRole,cap]);const made=await f.request('me/privacy-requests',{...input,subjectId:f.student},'staff'),id=made.body.data.id,definition=response(made.body.data.baselineReviewOn);assert.equal(made.body.data.portalRequesterCurrent,true);const pending=await f.request('privacy-requests/'+id+'/review',{expectedVersion:1,definition,reason:'Synthetic pending portal response'},'manager');assert.equal(pending.response.status,202,JSON.stringify(pending.body));assert.equal((await f.request('family-relationships/'+f.relationship.id+'/change',{expectedVersion:1,relationship:'authorized_contact',reason:'Synthetic recipient authority ended'})).response.status,200);assert.equal((await f.approve(pending.body.approval.id)).response.status,409);assert.equal((await f.request('privacy-requests/'+id+'/review',{expectedVersion:1,definition,reason:'Synthetic unavailable portal attempt'})).response.status,409);const record=(await f.request('privacy-requests/'+id)).body.data;assert.equal(record.portalRequesterCurrent,false);assert.equal(record.state,'received');const stamp=(await f.pg.query<{at:string}>(`SELECT to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') at`)).rows[0].at,offline=await f.request('privacy-requests/'+id+'/review',{expectedVersion:1,definition:{...definition,delivery:{method:'offline',reference:'PRIVATE human-attested identity and offline response',deliveredAt:stamp}},reason:'Synthetic independently reviewed offline handling'});assert.equal(offline.response.status,200,JSON.stringify(offline.body));assert.equal(offline.body.data.externalDeliveryVerified,false);assert.equal(offline.body.data.state,'responded');assert.equal((await f.request('privacy-requests/'+id,undefined,'staff')).response.status,404);
 }finally{await f.pg.close();}
});
test('privacy bot may prepare a scoped response but a verified upper human must approve it',async()=>{
 const f=await operationsFixture();try{for(const cap of ['privacy-requests.view','privacy-requests.edit'])await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,$3,'allow')",[f.a,f.managerRole,cap]);const created=await f.request('me/privacy-requests',input,'staff'),id=created.body.data.id,probe=await f.request('people',undefined,'bot');if(probe.response.status===401)await f.refreshBotCredential();else assert.equal(probe.response.status,200);const pending=await f.request('privacy-requests/'+id+'/review',{expectedVersion:1,definition:response(created.body.data.baselineReviewOn),reason:'Synthetic bot-prepared response'},'bot');assert.equal(pending.response.status,202,JSON.stringify(pending.body));assert.equal((await f.approve(pending.body.approval.id,'bot')).response.status,403);assert.equal((await f.request('privacy-requests/'+id,undefined,'staff')).body.data.state,'received');assert.equal((await f.approve(pending.body.approval.id)).response.status,200);assert.equal((await f.request('privacy-requests/'+id,undefined,'staff')).body.data.state,'responded');assert.equal((await f.request('privacy-requests/'+id,undefined,'bot')).response.status,200);await f.pg.query("DELETE FROM public.role_permissions WHERE role_id=$1 AND capability='privacy-requests.edit'",[f.managerRole]);assert.equal((await f.request('privacy-requests/'+id+'/review',{expectedVersion:2,definition:{...response(created.body.data.baselineReviewOn),state:'under_review',delivery:null},reason:'Must not bypass revoked editor rights'},'bot')).response.status,403);assert.equal((await f.pg.query('SELECT * FROM public.privacy_request_revisions')).rows.length,2);
 }finally{await f.pg.close();}
});
